const navbar=document.getElementById("navbar");window.addEventListener("scroll",()=>{navbar.classList.toggle("scrolled",window.scrollY>40)});const mobileMenu=document.getElementById("mobileMenu"),navLinks=document.getElementById("navLinks");mobileMenu.addEventListener("click",()=>{navLinks.style.display="flex"===navLinks.style.display?"none":"flex",navLinks.style.position="absolute",navLinks.style.top="70px",navLinks.style.left="0",navLinks.style.right="0",navLinks.style.background="rgba(6,6,15,.97)",navLinks.style.flexDirection="column",navLinks.style.padding="24px",navLinks.style.gap="20px",navLinks.style.borderBottom="1px solid #1e1e3a"}),document.querySelectorAll(".faq-q").forEach(e=>{e.addEventListener("click",()=>{const t=e.parentElement,n=t.classList.contains("open");document.querySelectorAll(".faq-item").forEach(e=>e.classList.remove("open")),n||t.classList.add("open")})});const discounts={monthly:0,"3months":.2,"6months":.3,"12months":.5},months={monthly:1,"3months":3,"6months":6,"12months":12};document.querySelectorAll(".period-btn").forEach(e=>{e.addEventListener("click",()=>{document.querySelectorAll(".period-btn").forEach(e=>e.classList.remove("active")),e.classList.add("active");const t=e.dataset.period,n=discounts[t];document.querySelectorAll(".price-num").forEach(e=>{const t=parseFloat(e.dataset.base);e.textContent=0===n?Number.isInteger(t)?t:t.toFixed(2):Math.round(t*(1-n))}),document.querySelectorAll(".price-period").forEach(e=>{e.textContent="monthly"===t?"/mo":`/${t.replace("months","mo")}`})})}),document.querySelectorAll('a[href*="Profileo.Setup"]').forEach(e=>{e.addEventListener("click",function(){"function"==typeof gtag&&gtag("event","download",{event_category:"App",event_label:document.title,file_name:"Profileo.Setup.1.3.5.exe",page_location:window.location.href})})});const observer=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.style.opacity="1",e.target.style.transform="translateY(0)")})},{threshold:.1});document.querySelectorAll(".feature-card, .price-card, .faq-item, .auto-content, .auto-visual").forEach(e=>{e.style.opacity="0",e.style.transform="translateY(20px)",e.style.transition="opacity 0.5s, transform 0.5s",observer.observe(e)});